                Health


            Rating System

                Rate this product: 
                ★
                ★
                ★
                ★
                ★

            Problem: SPAN elements lack semantic roles and keyboard event handlers!





        VIOLATION 7: Modal dialogs with poor keyboard handling

            User Profile Modal
            Edit Profile



                    ×
                    Edit Profile
                    Name: 
                    Email: 
                    Save Changes
                    Cancel


            Problem: Modal lacks focus management and Escape key handling!





        VIOLATION 8: Drag and drop without keyboard alternative

            Task Board - Drag to Reorder


                    To Do

                        Task 1: Review documents


                        Task 2: Update website



                    In Progress

                        Task 3: Database migration



                    Done

                        Task 4: Fix security issue



            Problem: Task management requires mouse for drag and drop!





        Expected Scanner Results
        WCAG 2.1.1 & 2.1.3 Violations Found:

            8 DIV elements styled as buttons without keyboard support
            4 clickable images/gallery items without tabindex or keyboard handlers
            2 custom dropdowns lacking ARIA patterns and keyboard navigation
            3 interactive map regions without keyboard access
            2 custom sliders requiring mouse interaction only
            8 SPAN elements with click handlers lacking semantic roles
            1 modal dialog with poor keyboard handling
            6 drag-and-drop interactions without keyboard alternatives

        Total Expected Violations: 34+ keyboard accessibility failures
        Confidence Level: High (missing semantic elements and attributes are detectable)



        function playPrevious() { alert('Previous track (not accessible!)'); }
        function togglePlay() { alert('Play/Pause (not accessible!)'); }
        function playNext() { alert('Next track (not accessible!)'); }
        function toggleMute() { alert('Mute/Unmute (not accessible!)'); }

        function viewProduct(id) { alert('View product ' + id + ' (not accessible!)'); }

        function toggleDropdown(type) {
            const dropdown = document.getElementById(type + 'Dropdown');
            dropdown.classList.toggle('show');
        }

        function selectCategory(cat) { alert('Selected category: ' + cat); }
        function sortBy(method) { alert('Sort by: ' + method); }

        function showOffice(location) { alert('Office location: ' + location + ' (not accessible!)'); }

        function moveSlider(event) { alert('Slider moved (not accessible!)'); }
        function moveVolumeSlider(event) { alert('Volume adjusted (not accessible!)'); }

        function filterByTag(tag) { alert('Filter by tag: ' + tag + ' (not accessible!)'); }
        function rate(stars) { alert('Rated ' + stars + ' stars (not accessible!)'); }

        function openModal() {
            document.getElementById('profileModal').style.display = 'block';
        }

        function closeModal() {
            document.getElementById('profileModal').style.display = 'none';
        }

        function saveProfile() { alert('Profile saved (not accessible!)'); }

        function allowDrop(ev) { ev.preventDefault(); }
        function drag(ev) { ev.dataTransfer.setData("text", ev.target.id); }
        function drop(ev) {
            ev.preventDefault();
            const data = ev.dataTransfer.getData("text");
            ev.target.appendChild(document.getElementById(data));
        }

        // Close dropdowns when clicking outside
        window.onclick = function(event) {
            if (!event.target.matches('.dropdown-trigger')) {
                const dropdowns = document.getElementsByClassName("dropdown-content");
                for (let i = 0; i < dropdowns.length; i++) {
                    dropdowns[i].classList.remove('show');
                }
            }
        }
